/// Clube de uma liga estrangeira.
class WorldClub {
  final String league;
  final String name;
  final String shortName;
  final String stadium;
  final String coach;
  final int base;
  final int capacity;
  final List<String> squad;
  const WorldClub(this.league, this.name, this.shortName, this.stadium, this.coach, this.base, this.capacity, this.squad);

  int get stars => base >= 83 ? 5 : base >= 79 ? 4 : base >= 75 ? 3 : 2;
}

